size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image,
                           QuantumType quantum_type, unsigned char *compact_pixels,
                           MagickOffsetType size_offset, MagickBooleanType separate,
                           ExceptionInfo *exception) {
  size_t count = 0;
  size_t number_pixels = image->rows * image->columns;
  ssize_t y;
  unsigned char *pixels = NULL;

  pixels = (unsigned char *) AcquireMemory(number_pixels * sizeof(*pixels));
  if (pixels == (unsigned char *) NULL) {
    ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
                         "UnableToAcquireMemory", "\n");
    return 0;
  }

  for (y = 0; y < (ssize_t) image->rows; y++) {
    register Quantum *p;
    register ssize_t x;
    ssize_t length = 0;

    p = AcquireImagePixels(next_image, 0, y, image->columns, 1, exception);
    if (p == (Quantum *) NULL)
      break;

    for (x = 0; x < (ssize_t) image->columns; x++) {
      Quantum pixel;
      pixel = GetPixelInfoPixel(quantum_type, p, next_image);
      pixels[length++] = (unsigned char) ScaleQuantumToChar(pixel);
      p++;
    }

    count += WriteBlobData(psd_info->file, size_offset, length, pixels);
    size_offset += length;
  }

  pixels = (unsigned char *) RelinquishMagickMemory(pixels);
  return count;
}

size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image, QuantumType quantum_type,
                           unsigned char *compact_pixels, MagickOffsetType size_offset,
                           MagickBooleanType separate, ExceptionInfo *exception) {
  size_t written = 0;
  register const Quantum *p;
  register Quantum *q;
  ssize_t y;
  unsigned char *pixels = NULL;
  size_t length;

  (void) psd_info;  // Unused parameter
  (void) image_info;  // Unused parameter
  (void) image;  // Unused parameter
  (void) quantum_type;  // Unused parameter
  (void) separate;  // Unused parameter

  length = next_image->rows * next_image->columns * 4;

  pixels = (unsigned char *) AcquireMemory(length);
  if (pixels == (unsigned char *) NULL) {
    ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
                         "UnableToAllocateMemory", "\n");
    return 0;
  }

  for (y = 0; y < (ssize_t) next_image->rows; y++) {
    p = GetVirtualPixels(next_image, 0, y, next_image->columns, 1, exception);
    if (p == (const Quantum *) NULL) {
      pixels = (unsigned char *) RelinquishMemory(pixels);
      return 0;
    }

    q = (Quantum *) pixels;
    ExportQuantumPixels(next_image, (Cache) NULL, (QuantumType) GrayQuantum, q, exception);
    written += (size_t) (next_image->columns * 4);
  }

  (void) memcpy(compact_pixels + size_offset, pixels, length);
  pixels = (unsigned char *) RelinquishMemory(pixels);
  return written;
}

size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image,
                           QuantumType quantum_type, unsigned char *compact_pixels,
                           MagickOffsetType size_offset, MagickBooleanType separate,
                           ExceptionInfo *exception) {
  size_t length = 0;
  ssize_t y;
  MagickBooleanType status;
  unsigned char *pixels = NULL;

  for (y = 0; y < (ssize_t) image->rows; y++) {
    pixels = (unsigned char *) AcquireQuantumInfoPixels(image, next_image, quantum_type, 0, y, image->columns, 1, exception);
    if (pixels == NULL)
      break;

    if (psd_info->compression == PSDCompressionRLE) {
      // RLE compression logic
      length += WriteRLECompressedPixels(psd_info, image, quantum_type, pixels, separate, exception);
    }
    else if (psd_info->compression == PSDCompressionZIP) {
      // ZIP compression logic
      length += WriteZIPCompressedPixels(psd_info, image, quantum_type, pixels, separate, exception);
    }
    else {
      // No compression
      length += WriteRawPixels(psd_info, image, quantum_type, pixels, separate, exception);
    }

    if (pixels != NULL)
      pixels = (unsigned char *) RelinquishMagickMemory(pixels);
  }

  if (compact_pixels != NULL) {
    compact_pixels = (unsigned char *) RelinquishMagickMemory(compact_pixels);
    compact_pixels = (unsigned char *) AcquireQuantumInfoMemory(image, length, exception);
    if (compact_pixels == NULL) {
      ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", "WritePSDChannelBlob");
    }
  }

  return length;
}

